<?php
 namespace QQWorld\Customer\Test\Unit\Model; use QQWorld\Customer\Model\CustomerExtractor; class CustomerExtractorTest extends \PHPUnit\Framework\TestCase { protected $customerExtractor; protected $formFactory; protected $customerFactory; protected $storeManager; protected $customerGroupManagement; protected $dataObjectHelper; protected $request; protected $customerForm; protected $customerData; protected $store; protected $customerGroup; protected function setUp() { $this->formFactory = $this->getMockForAbstractClass( \QQWorld\Customer\Model\Metadata\FormFactory::class, [], '', false, false, true, ['create'] ); $this->customerFactory = $this->getMockForAbstractClass( \QQWorld\Customer\Api\Data\CustomerInterfaceFactory::class, [], '', false, false, true, ['create'] ); $this->storeManager = $this->getMockForAbstractClass( \QQWorld\Store\Model\StoreManagerInterface::class, [], '', false ); $this->customerGroupManagement = $this->getMockForAbstractClass( \QQWorld\Customer\Api\GroupManagementInterface::class, [], '', false ); $this->dataObjectHelper = $this->createMock(\QQWorld\Framework\Api\DataObjectHelper::class); $this->request = $this->getMockForAbstractClass(\QQWorld\Framework\App\RequestInterface::class, [], '', false); $this->customerForm = $this->createMock(\QQWorld\Customer\Model\Metadata\Form::class); $this->customerData = $this->getMockForAbstractClass( \QQWorld\Customer\Api\Data\CustomerInterface::class, [], '', false ); $this->store = $this->getMockForAbstractClass( \QQWorld\Store\Api\Data\StoreInterface::class, [], '', false ); $this->customerGroup = $this->getMockForAbstractClass( \QQWorld\Customer\Api\Data\GroupInterface::class, [], '', false ); $this->customerExtractor = new CustomerExtractor( $this->formFactory, $this->customerFactory, $this->storeManager, $this->customerGroupManagement, $this->dataObjectHelper ); } public function testExtract() { $customerData = [ 'firstname' => 'firstname', 'lastname' => 'firstname', 'email' => 'email.example.com', ]; $this->formFactory->expects($this->once()) ->method('create') ->with('customer', 'form-code') ->willReturn($this->customerForm); $this->customerForm->expects($this->once()) ->method('extractData') ->with($this->request) ->willReturn($customerData); $this->customerForm->expects($this->once()) ->method('compactData') ->with($customerData) ->willReturn($customerData); $this->customerForm->expects($this->once()) ->method('getAllowedAttributes') ->willReturn(['group_id' => 'attribute object']); $this->customerFactory->expects($this->once()) ->method('create') ->willReturn($this->customerData); $this->dataObjectHelper->expects($this->once()) ->method('populateWithArray') ->with($this->customerData, $customerData, \QQWorld\Customer\Api\Data\CustomerInterface::class) ->willReturn($this->customerData); $this->storeManager->expects($this->once()) ->method('getStore') ->willReturn($this->store); $this->store->expects($this->exactly(2)) ->method('getId') ->willReturn(1); $this->customerGroupManagement->expects($this->once()) ->method('getDefaultGroup') ->with(1) ->willReturn($this->customerGroup); $this->customerGroup->expects($this->once()) ->method('getId') ->willReturn(1); $this->customerData->expects($this->once()) ->method('setGroupId') ->with(1); $this->store->expects($this->once()) ->method('getWebsiteId') ->willReturn(1); $this->customerData->expects($this->once()) ->method('setWebsiteId') ->with(1); $this->customerData->expects($this->once()) ->method('setStoreId') ->with(1); $this->assertSame($this->customerData, $this->customerExtractor->extract('form-code', $this->request)); } } 